WITH RECURSIVE R1 AS (
    SELECT C1, C2, 0 AS LVL FROM DB1.S2.T1 WHERE C2 IS NULL
    UNION ALL
    SELECT t.C1, t.C2, r.LVL + 1
    FROM DB1.S2.T1 t JOIN R1 r ON t.C2 = r.C1
),
R2 AS (
    SELECT
        C1,
        SUM(C3) AS TOTAL,
        ROW_NUMBER() OVER (PARTITION BY C2 ORDER BY C1) AS RN,
        SUM(SUM(C3)) OVER (
            PARTITION BY C2 ORDER BY C1
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ) AS RUNNING
    FROM DB1.S2.T2
    GROUP BY C1, C2
)
SELECT C1, TOTAL, RUNNING
FROM R2
QUALIFY ROW_NUMBER() OVER (PARTITION BY C2 ORDER BY TOTAL DESC) = 1
ORDER BY C1;
